from pybricks.parameters import Direction, Port, Stop
from pybricks.pupdevices import Motor
from pybricks.robotics import DriveBase
from pybricks.tools import wait

# Set up.
Left_attachment = Motor(Port.C, Direction.COUNTERCLOCKWISE)
Right__attachment = Motor(Port.E, Direction.CLOCKWISE)
Left_drive = Motor(Port.B, Direction.COUNTERCLOCKWISE)
Right_drive = Motor(Port.F, Direction.CLOCKWISE)
drive_base = DriveBase(Left_drive, Right_drive, 56, 114)

def phoenix_gyro_spin_turn_the_old_way(fast_speed, fast_end_angle, slow_speed, final_end_angle, direction, phoenix_drive_base, left_drive_motor, right_drive_motor):
    phoenix_drive_base.use_gyro(True)
    phoenix_drive_base.reset(0, 0)
    if 'right' in direction:
        while not phoenix_drive_base.angle() >= fast_end_angle:
            left_drive_motor.run(fast_speed)
            right_drive_motor.run(0 - fast_speed)
            wait(0.01)
        while not phoenix_drive_base.angle() >= final_end_angle:
            left_drive_motor.run(slow_speed)
            right_drive_motor.run(0 - slow_speed)
            wait(0.01)
        phoenix_drive_base.brake()
    else:
        while not phoenix_drive_base.angle() <= fast_end_angle:
            right_drive_motor.run(fast_speed)
            left_drive_motor.run(0 - fast_speed)
            wait(0.01)
        while not phoenix_drive_base.angle() <= final_end_angle:
            right_drive_motor.run(slow_speed)
            left_drive_motor.run(0 - slow_speed)
            wait(0.01)
        phoenix_drive_base.brake()


# The main program starts here.
drive_base.straight(400)
print('a')
wait(3)
Right__attachment.run_angle(500, -360)
print('b')
wait(1)
drive_base.straight(-41)
print('c')
wait(1)
Right__attachment.run_angle(1, 210)
print('d')
wait(1)
Right__attachment.run_angle(500, -300)
wait(1)
Right__attachment.run_angle(500, 20)
wait(1)
Right__attachment.run_angle(500, -40)
wait(1)
Right__attachment.run_angle(500, 20)
wait(1)
Right__attachment.run_angle(500, -40)
